mapper.select:
SELECT  FROM journey_definition d WHERE tenant_id=#{tenant} AND journey_id > #{after} AND version=(SELECT MAX(v.version) FROM journey_definition v WHERE v.tenant_id=d.tenant_id AND v.journey_id=d.journey_id)
    AND (LOCATE(#{filter.q},journey_id)>0 OR LOCATE(#{filter.q},store_id)>0 OR LOCATE(#{filter.q},JSON_UNQUOTE(JSON_EXTRACT(definition_json,'$.name')))>0)
    AND status=#{filter.status} ORDER BY journey_id LIMIT #{limit}

SELECT  FROM journey_instance WHERE tenant_id=#{tenant} AND member_id=#{member} AND instance_id > #{after}
    AND (LOCATE(#{filter.q},instance_id)>0 OR LOCATE(#{filter.q},journey_id)>0 OR LOCATE(#{filter.q},member_id)>0)
    AND status=#{filter.status} ORDER BY instance_id LIMIT #{limit}

SELECT tenant_id FROM (
  SELECT DISTINCT tenant_id FROM journey_instance FORCE INDEX(idx_journey_global_due) WHERE tenant_id>#{after} AND status IN ('RUNNING','WAITING') AND due_at<=#{now}
  UNION
  SELECT DISTINCT tenant_id FROM journey_instance FORCE INDEX(idx_journey_global_deadline) WHERE tenant_id>#{after} AND status IN ('RUNNING','WAITING','ISOLATED') AND deadline<=#{now}
  UNION
  SELECT s.tenant_id FROM journey_lifecycle_scan s JOIN journey_definition d ON d.tenant_id=s.tenant_id AND d.journey_id=s.journey_id AND d.version=s.journey_version WHERE s.tenant_id>#{after} AND s.status<>'ISOLATED' AND s.next_due<=#{now} AND d.status='PUBLISHED' AND d.valid_from<=#{now} AND d.valid_to>#{now}
) t ORDER BY tenant_id LIMIT #{limit}

SELECT  FROM journey_lifecycle_scan s WHERE tenant_id=#{tenant} AND journey_id>#{after} AND journey_version=(SELECT MAX(v.journey_version) FROM journey_lifecycle_scan v WHERE v.tenant_id=s.tenant_id AND v.journey_id=s.journey_id)
    AND (LOCATE(#{filter.q},s.journey_id)>0)
    AND s.status=#{filter.status} ORDER BY journey_id LIMIT #{limit}
